const renderTpl = (tpl, labels) => String(tpl || '').replace(/{{\s*\$labels\.([a-zA-Z_][a-zA-Z0-9_]*)\s*}}/g, (_, k) => (labels && labels[k] != null ? labels[k] : ''));
const groups = ($input.all()[0]?.json?.data?.groups) || [];
const firing = [];
for (const g of groups) {
  for (const r of (g.rules || [])) {
    if (r.type !== 'alerting') continue;
    if (r.state !== 'firing') continue;
    const labels = r.labels || {};
    const annotations = r.annotations || {};
    const alertsArr = r.alerts || [];
    if (alertsArr.length === 0) {
      const target = labels.name || labels.instance || 'unknown';
      firing.push({
        alertname: r.name || labels.alertname || 'Unknown',
        severity: labels.severity || 'warning',
        instance: labels.instance || 'unknown',
        name: labels.name || '',
        job: labels.job || 'unknown',
        summary: annotations.summary || '',
        description: renderTpl(annotations.description, labels),
        startsAt: new Date().toISOString(),
        fingerprint: ((r.name || 'alert') + '-' + target).replace(/[^a-z0-9-]/gi, '-')
      });
    } else {
      for (const a of alertsArr) {
        const al = a.labels || {};
        const target = al.name || al.instance || 'unknown';
        firing.push({
          alertname: al.alertname || r.name || 'Unknown',
          severity: al.severity || 'warning',
          instance: al.instance || 'unknown',
          name: al.name || '',
          job: al.job || 'unknown',
          summary: annotations.summary || '',
          description: renderTpl(annotations.description, al),
          startsAt: a.activeAt || new Date().toISOString(),
          fingerprint: ((al.alertname || r.name || 'alert') + '-' + target).replace(/[^a-z0-9-]/gi, '-')
        });
      }
    }
  }
}
return firing.map(a => ({ json: a }));

const alerts = $('Extraer Alertas Firing').all().map(i => i.json);
let existingIssues = [];
try {
  const issuesNode = $('MantisBT – Buscar Issues Existentes').first()?.json;
  existingIssues = (issuesNode && issuesNode.issues) || [];
} catch(e) {
  existingIssues = [];
}

return alerts.map(alert => {
  const fp = alert.fingerprint;
  const severity = alert.severity || 'warning';
  const alertname = alert.alertname || 'Unknown';
  const instance = alert.instance || 'unknown';
  const name = alert.name || '';
  const job = alert.job || 'unknown';

  const isDuplicate = existingIssues.some(issue => {
    const s = issue.summary || '';
    const isOpen = issue.status?.name !== 'closed' && issue.status?.name !== 'resolved';
    return isOpen && s.includes(fp);
  });

  // Mapeo de Categoría y Especialista Responsable (Handler)
  // Especialistas disponibles en MantisBT:
  // - facundo_db (DBA / Data) -> Database
  // - gonzalo_dev (Backend / Lead) -> Backend
  // - aldo_front (Frontend / DevOps) -> Frontend
  // - sonia_dev (Monitoreo / Infra) -> Infra / CI-CD
  let categoryName = 'Infra / CI-CD';
  let handlerName = 'sonia_dev';

  const targetStr = ((name || '') + ' ' + (instance || '') + ' ' + (alertname || '') + ' ' + (job || '')).toLowerCase();

  if (targetStr.includes('postgres') || targetStr.includes('db-node') || targetStr.includes('etcd') || targetStr.includes('patroni') || targetStr.includes('pgadmin')) {
    categoryName = 'Database';
    handlerName = 'facundo_db';
  } else if (targetStr.includes('backend')) {
    categoryName = 'Backend';
    handlerName = 'gonzalo_dev';
  } else if (targetStr.includes('frontend')) {
    categoryName = 'Frontend';
    handlerName = 'aldo_front';
  } else {
    categoryName = 'Infra / CI-CD';
    handlerName = 'sonia_dev';
  }

  // Mapeo Severidad MantisBT: feature(10), trivial(20), text(30), tweak(40), minor(50), major(60), crash(70), block(80)
  // 'critical' de Prometheus se mapea a 'crash' (70) en MantisBT
  // 'warning' de Prometheus se mapea a 'major' (60) en MantisBT
  const sevLower = String(severity || '').toLowerCase();
  let mantisSeverity = 'minor';
  let mantisPriority = 'normal';

  if (sevLower === 'critical' || sevLower === 'crash') {
    mantisSeverity = 'crash';
    mantisPriority = 'urgent';
  } else if (sevLower === 'warning' || sevLower === 'major') {
    mantisSeverity = 'major';
    mantisPriority = 'high';
  } else {
    mantisSeverity = 'minor';
    mantisPriority = 'normal';
  }

  const targetDisplay = name ? name : instance;
  const sumTxt = ('[ALERTA][' + mantisSeverity.toUpperCase() + '] ' + alertname + ' - ' + targetDisplay + ' [' + fp + ']').slice(0, 255);
  const desc = '## Alerta Prometheus\n\n'
    + '**Nombre:** ' + alertname + '\n'
    + '**Severidad:** ' + mantisSeverity + ' (' + severity + ')\n'
    + '**Prioridad:** ' + mantisPriority + '\n'
    + '**Categoría:** ' + categoryName + '\n'
    + '**Especialista Asignado:** ' + handlerName + '\n'
    + (name ? ('**Contenedor:** ' + name + '\n') : '')
    + '**Instancia:** ' + instance + '\n'
    + '**Job:** ' + String(job || '') + '\n\n'
    + '### Resumen\n' + String(alert.summary || '') + '\n\n'
    + '### Descripción\n' + String(alert.description || '') + '\n\n'
    + '### Inicio\n' + String(alert.startsAt || '') + '\n\n'
    + '*automatizado por n8n - WF1 Alertas desde Prometheus*';

  return {
    json: {
      ...alert,
      isDuplicate,
      summary: sumTxt,
      description: desc,
      fingerprint: fp,
      categoryName,
      handlerName,
      mantisSeverity,
      mantisPriority
    }
  };
});

const issue = $input.item.json;
const issueId = issue.issue?.id || issue.id || 'desconocido';
const summary = issue.issue?.summary || issue.summary || 'sin resumen';
console.log('[WF1] Issue creado en MantisBT: ID=' + issueId + ' | ' + summary);
return { json: { resultado: 'issue_creado', issueId, summary, timestamp: new Date().toISOString() } };
